import AppKit
import AVFoundation
import SwiftUI

enum SpeechVoices {
 static func spoken(_ value:String)->String {
  var text=value.replacingOccurrences(of:"```[\\s\\S]*?```",with:" I’ve included the code in the bubble. ",options:.regularExpression)
  text=text.replacingOccurrences(of:"\\[([^\\]]+)\\]\\([^)]+\\)",with:"$1",options:.regularExpression).replacingOccurrences(of:"https?://\\S+",with:"the linked page",options:.regularExpression)
  return String(text.replacingOccurrences(of:"[*#`_]",with:"",options:.regularExpression).trimmingCharacters(in:.whitespacesAndNewlines).prefix(2400))
 }
}
@MainActor final class VoiceController:NSObject,ObservableObject,AVAudioPlayerDelegate {
 let model:BuddyModel;let dictation=Dictation();let neural=NeuralSpeech()
 @Published var active=false
 private var player:AVAudioPlayer?;private var queue:[URL]=[];private var playingURL:URL?;private var speechID:String?;private var generationDone=false;private var suppressReply=false
 init(model:BuddyModel){self.model=model;super.init()
  neural.onStatus={[weak self] status,progress,ready in guard let self else{return};self.model.neuralStatus=status;self.model.neuralProgress=progress;self.model.neuralReady=ready;self.model.neuralInstalling = !ready && !status.contains("attention") && !status.contains("stopped")}
  neural.onAudio={[weak self] id,url in guard let self else{return};if self.speechID==id{self.queue.append(url);self.playNext()}else{try? FileManager.default.removeItem(at:url)}}
  neural.onDone={[weak self] id in guard let self,self.speechID==id else{return};self.generationDone=true;self.finishIfReady()}
  neural.onError={[weak self] message in guard let self else{return};self.stop();self.model.neuralInstalling=false;self.model.neuralReady=false;self.model.notice=message}
  dictation.onEnded={[weak self] error in guard let self else{return};self.model.notice=error;self.active=false;self.model.handsFree=false;self.model.listening=false}
  dictation.autoSubmit=true;dictation.onText={[weak self] text in self?.model.draft=text}
  dictation.onFinal={[weak self] text in guard let self,self.active,!text.isEmpty else{return};self.model.listening=false;self.model.draft=text;self.model.agentMode=true;Task{await self.model.send();self.suppressReply=false;if self.active && !self.model.voiceReplies && self.model.plan.isEmpty && self.model.notice.isEmpty{self.start()};if !self.model.notice.isEmpty && !self.model.busy && !self.model.speaking && !self.model.voiceRendering{self.stop()}}}
  model.speak={[weak self] text in self?.say(text)};model.stopDictation={[weak self] in self?.stop()};model.startVoice={[weak self] in self?.toggle()};model.prepareNeuralVoice={[weak self] in self?.neural.load()};model.cancelNeuralVoice={[weak self] in guard let self else{return};self.shutdown();self.model.neuralReady=false;self.model.neuralInstalling=false;self.model.neuralStatus="Voice setup paused"}
  if NeuralSpeech.isInstalled{neural.load()}
 }
 func toggle(){(active || model.speaking || model.voiceRendering) ? stop():start()}
 func start(){guard model.signedIn else{model.notice="Sign in through Settings before starting a conversation.";return};guard !model.busy,!model.speaking,!model.voiceRendering else{return};active=true;suppressReply=false;model.handsFree=true;dictation.allowAppleService=UserDefaults.standard.bool(forKey:"apple-speech-fallback");Task{await dictation.start();guard active else{dictation.stop();return};model.listening=dictation.recording;if !dictation.error.isEmpty{model.notice=dictation.error;active=false;model.handsFree=false}}}
 func stop(){suppressReply=model.busy;active=false;model.handsFree=false;model.listening=false;dictation.stop();cancelSpeech()}
 func cancelSpeech(){if let id=speechID{neural.cancel(id)};speechID=nil;player?.stop();player=nil;for url in queue+[playingURL].compactMap({$0}){try? FileManager.default.removeItem(at:url)};queue=[];playingURL=nil;model.speaking=false;model.voiceRendering=false}
 func say(_ text:String){if suppressReply && model.busy{suppressReply=false;return};suppressReply=false;dictation.stop();model.listening=false;cancelSpeech();let spoken=SpeechVoices.spoken(text);guard !spoken.isEmpty else{return};let id=UUID().uuidString.lowercased();speechID=id;generationDone=false;model.voiceRendering=true;neural.speak(id:id,text:spoken,voice:model.neuralVoiceID,speed:min(1.2,max(0.8,model.voiceSpeed)))}
 private func playNext(){guard player==nil,!queue.isEmpty else{return};let url=queue.removeFirst();do{let audio=try AVAudioPlayer(contentsOf:url);audio.delegate=self;audio.prepareToPlay();guard audio.play() else{throw APIError(message:"Audio output unavailable")};player=audio;playingURL=url;model.voiceRendering=false;model.speaking=true}catch{try? FileManager.default.removeItem(at:url);stop();model.notice="The neural voice was generated, but macOS could not play it. Check your audio output."}}
 private func finishIfReady(){guard generationDone,queue.isEmpty,player==nil,speechID != nil else{return};speechID=nil;model.speaking=false;model.voiceRendering=false;if active,model.plan.isEmpty{Task{try? await Task.sleep(for:.milliseconds(400));if active{start()}}}}
 nonisolated func audioPlayerDidFinishPlaying(_ player:AVAudioPlayer,successfully flag:Bool){Task{@MainActor in guard self.player===player else{return};self.player=nil;if let url=playingURL{try? FileManager.default.removeItem(at:url)};playingURL=nil;model.speaking=false;playNext();finishIfReady()}}
 func shutdown(){stop();neural.shutdown()}
}

struct PetBubble:View {
 @ObservedObject var model:BuddyModel;@ObservedObject var voice:VoiceController
 var close:()->Void
 var dark:Bool{model.appearance=="dark"};var line:Color{dark ? .white.opacity(0.16):.black.opacity(0.1)}
 var voiceIsOn:Bool{voice.active || model.speaking || model.voiceRendering}
 var status:String{model.listening ? "Listening":model.busy ? "Thinking":model.speaking ? "Speaking":model.voiceRendering ? "Creating voice":"Here with you"}
 var reply:String?{model.messages.last(where:{$0.role=="assistant"})?.content}
 var body:some View{VStack(alignment:.leading,spacing:18){
  HStack(spacing:10){if let image=SpriteCache.image(model.buddyID,model.listening ? 3:0){Image(nsImage:image).resizable().interpolation(.none).scaledToFit().frame(width:29,height:32)};VStack(alignment:.leading,spacing:3){Text(model.buddy.name).font(.system(size:14,weight:.semibold,design:.rounded));HStack(spacing:4){Circle().fill(model.listening ? Color.green:model.busy ? .orange:Color.secondary.opacity(0.5)).frame(width:4,height:4);Text(status).font(.system(size:10)).foregroundStyle(.secondary)}};Spacer();Button{model.showConversation()}label:{Image(systemName:"slider.horizontal.3").frame(width:25,height:25)}.buttonStyle(.plain).help("Settings");Button{voice.stop();close()}label:{Image(systemName:"xmark").font(.system(size:11,weight:.semibold)).frame(width:25,height:25)}.buttonStyle(.plain).help("Close and stop microphone")}
  if !model.signedIn{Text("A little company.\nOne sign-in away.").font(.system(size:25,weight:.medium,design:.rounded));Text("Sign in once. This Mac can remember you.").font(.callout).foregroundStyle(.secondary);Button("Sign in to Thread"){model.showConversation()}.buttonStyle(.borderedProminent)}else{
   if let reply{VStack(alignment:.leading,spacing:10){ScrollView{Text(reply).font(.system(size:14)).lineSpacing(6).textSelection(.enabled).frame(maxWidth:.infinity,alignment:.leading)}.frame(minHeight:60,maxHeight:190);HStack(spacing:13){Button{NSPasteboard.general.clearContents();NSPasteboard.general.setString(reply,forType:.string)}label:{Image(systemName:"doc.on.doc")}.help("Copy reply");Button{model.speaking || model.voiceRendering ? voice.stop():voice.say(reply)}label:{Image(systemName:model.speaking || model.voiceRendering ? "stop.circle":"speaker.wave.2")}.help(model.speaking || model.voiceRendering ? "Stop speaking":"Read this reply");Spacer();if model.busy{ProgressView().controlSize(.small)}}.font(.system(size:12)).foregroundStyle(.secondary).buttonStyle(.plain)}}else{VStack(alignment:.leading,spacing:7){Text("What’s on your mind?").font(.system(size:24,weight:.medium,design:.rounded)).tracking(-0.5);Text("Say it out loud, or drop a thought here.").font(.system(size:12)).foregroundStyle(.secondary)}.padding(.vertical,9)}
   if let screen=model.screen{HStack(spacing:11){if let image=screen.image{Image(nsImage:image).resizable().scaledToFill().frame(width:64,height:43).clipped().clipShape(RoundedRectangle(cornerRadius:7))};VStack(alignment:.leading,spacing:3){Text("Your shared screen").font(.system(size:11,weight:.medium));Text("Attached to your next question only").font(.system(size:9)).foregroundStyle(.secondary)};Spacer();Button{model.screen=nil}label:{Image(systemName:"xmark.circle.fill").foregroundStyle(.secondary)}.buttonStyle(.plain).help("Remove screenshot")}.padding(10).background(Color.primary.opacity(0.035),in:RoundedRectangle(cornerRadius:11))}
   if let action=model.plan.first{approval(action)}
   composer
  }
  if !model.notice.isEmpty{HStack(alignment:.top,spacing:8){Image(systemName:"info.circle");Text(model.notice).font(.system(size:10)).fixedSize(horizontal:false,vertical:true);Spacer();Button{model.notice=""}label:{Image(systemName:"xmark")}.buttonStyle(.plain)}.foregroundStyle(.secondary).font(.system(size:10))}
 }.padding(20).frame(width:410).background(dark ? Color.black:Color(red:0.98,green:0.98,blue:0.975),in:RoundedRectangle(cornerRadius:23)).overlay(RoundedRectangle(cornerRadius:23).stroke(line)).preferredColorScheme(dark ? .dark:.light)}
 var composer:some View{VStack(alignment:.leading,spacing:9){
  VStack(alignment:.leading,spacing:13){TextField("Message \(model.buddy.name)…",text:$model.draft,prompt:Text("Message \(model.buddy.name)…").foregroundColor(dark ? .white.opacity(0.5):.black.opacity(0.55)),axis:.vertical).textFieldStyle(.plain).font(.system(size:14)).lineLimit(1...5).onSubmit{ask()}.padding(.top,3).frame(minHeight:29,alignment:.top)
   HStack(spacing:13){Menu{Button("Share a screenshot",systemImage:"viewfinder"){Task{await model.captureScreen()}};Button("Clear conversation",systemImage:"arrow.counterclockwise"){voice.stop();model.messages=[];model.plan=[];model.screen=nil;model.draft="";ScreenOverlay.shared.clear()};Button("Settings",systemImage:"slider.horizontal.3"){model.showConversation()}}label:{Image(systemName:"plus").font(.system(size:17,weight:.regular)).frame(width:23,height:26)}.menuStyle(.borderlessButton).menuIndicator(.hidden).fixedSize().help("Attach a screen or open conversation options")
    Button{Task{await model.captureScreen()}}label:{Image(systemName:"viewfinder").font(.system(size:16)).frame(width:25,height:26)}.buttonStyle(.plain).disabled(model.busy).help("Share your screen")
    Button{model.voiceReplies.toggle();if !model.voiceReplies{voice.stop()}}label:{Image(systemName:model.voiceReplies ? "speaker.wave.2":"speaker.slash").font(.system(size:14))}.buttonStyle(.plain).help(model.voiceReplies ? "Mute spoken replies":"Read replies aloud")
    Spacer()
    Button{voice.toggle()}label:{HStack(spacing:6){Image(systemName:voiceIsOn ? "stop.fill":"waveform").font(.system(size:12,weight:.medium));Text(voiceIsOn ? "Stop":"Voice").font(.system(size:11,weight:.medium))}.padding(.horizontal,11).frame(height:30).background(voiceIsOn ? Color.blue.opacity(0.12):Color.primary.opacity(0.055),in:Capsule()).foregroundStyle(voiceIsOn ? Color.blue:Color.primary)}.buttonStyle(.plain).disabled(model.busy && !voiceIsOn).help(voiceIsOn ? "Stop conversation":"Start voice conversation")
    Button{ask()}label:{Image(systemName:"arrow.up").font(.system(size:14,weight:.semibold)).frame(width:31,height:31).foregroundStyle(dark ? .black:.white).background(dark ? Color.white:Color.black,in:Circle()).opacity(model.draft.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty ? 0.25:1)}.buttonStyle(.plain).disabled(model.busy||model.draft.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty).keyboardShortcut(.return,modifiers:.command).help("Send question (Command-Return)")
   }.foregroundStyle(.secondary)
  }.padding(14).background(dark ? Color.black:Color.white,in:RoundedRectangle(cornerRadius:19)).overlay(RoundedRectangle(cornerRadius:19).stroke(model.listening ? Color.blue.opacity(0.5):line)).shadow(color:.black.opacity(dark ? 0:0.025),radius:8,y:3)
  HStack(spacing:5){if model.listening{Image(systemName:"waveform").foregroundStyle(.blue)};Text(model.listening ? "Listening · pause to send your turn":model.speaking ? "Tap stop to interrupt your buddy":"⌘↩ to send · ⌥⌘Space to talk").font(.system(size:9));Spacer();if model.screen != nil{Text("1 attachment").font(.system(size:9))}}.foregroundStyle(.secondary).padding(.horizontal,3)
 }}
 func approval(_ action:DesktopAction)->some View{VStack(alignment:.leading,spacing:11){HStack{Image(systemName:"hand.raised");Text("Your call").font(.system(size:11,weight:.semibold));Spacer();Text("APPROVAL NEEDED").font(.system(size:8,design:.monospaced)).foregroundStyle(.secondary)};Text(action.label).font(.system(size:13,weight:.semibold)).lineLimit(2);Text(action.explanation ?? "Review the target before continuing.").font(.system(size:11)).foregroundStyle(.secondary).lineSpacing(4);if let text=action.text{Text(text).font(.system(size:11)).lineLimit(4).textSelection(.enabled)};HStack{Button("Deny"){model.plan=[];ScreenOverlay.shared.clear();if voice.active{voice.start()}}.buttonStyle(.borderless);Spacer();Button("Approve this action"){Task{await model.approve(action)}}.buttonStyle(.borderedProminent).tint(.blue).controlSize(.small)}}.padding(14).background(Color.primary.opacity(0.03),in:RoundedRectangle(cornerRadius:13)).overlay(RoundedRectangle(cornerRadius:13).stroke(line))}
 func ask(){guard !model.busy,!model.draft.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty else{return};voice.stop();model.agentMode=true;Task{await model.send()}}
}
